pub fn is_palindrome(s: &str) -> bool {
    let mut set: HashSet<char> = HashSet::new();
    for c in s.chars() {
        if c.is_alphabetic() && c.is_digit(10) {
            set.insert(c);
        }
    }
    let mut i = 0;
    let mut j = set.len() - 1;
    while i < j {
        if !set.contains(&s[i]) {
            return false;
        }
        if !set.contains(&s[j]) {
            return false;
        }
        i += 1;
        j -= 1;
    }
    true
}

