pub fn rotate_left(v: &[i32], k: usize) -> Vec<i32> {
    let mut res = v.to_vec();
    let mut len = res.len();
    if k >= len {
        return res;
    }
    let mut i = 0;
    while i < k {
        let j = len - 1 - i;
        let temp = res[j];
        res[j] = res[i];
        res[i] = temp;
        i += 1;
    }
    res
}

